"use client"

import * as React from "react"

import { AGENTS, agent as findAgent, maxRounds } from "@/lib/agents/registry"
import {
  deliveredTo,
  loadTasks,
  newTask,
  running,
  saveTasks,
  when,
  type Task,
} from "@/lib/agents/inbox"
import { runAgent } from "@/lib/agents/run-client"
import { Prose, RunMeta, RunSteps } from "@/app/agents/transcript"
import { AppSidebar } from "@/registry/blocks/sidebar-09/components/app-sidebar"
import { Button } from "@govblock/ui/components/nova/button"
import { Textarea } from "@govblock/ui/components/nova/textarea"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@govblock/ui/components/ny4/breadcrumb"
import { Separator } from "@govblock/ui/components/ny4/separator"
import {
  SidebarInset,
  SidebarProvider,
  SidebarTrigger,
} from "@govblock/ui/components/ny4/sidebar"

// The Agentic Inbox — shadcn's sidebar-09 mail block, repurposed.
//
// Live chat is what /agents already is. This is its long-form sibling: a task
// goes in, an agent works it across many rounds, and the finished report is
// read here like a delivered message with the run it did collapsed underneath.
// The same round loop, the same renderer, a different frame around them.
//
// v1 runs the task in this tab. That is the honest shape for a public site with
// no accounts: tasks are kept in this browser, and the header says so rather
// than letting anyone assume a server is holding them. What makes it feel
// delivered anyway is Discord — the agent posts the finished report into the
// channel, so it arrives somewhere that outlives the tab.

const INBOX_AGENTS = AGENTS.filter((a) => a.inbox || a.agentic)

export default function Page() {
  const [tasks, setTasks] = React.useState<Task[]>([])
  const [selected, setSelected] = React.useState<string | null>(null)
  const [composing, setComposing] = React.useState(false)
  const [slug, setSlug] = React.useState(INBOX_AGENTS[0]?.slug ?? "researcher")
  const [tasking, setTasking] = React.useState("")
  const [restored, setRestored] = React.useState(false)

  React.useEffect(() => {
    const stored = loadTasks()
    // A task that was running when the tab closed did not survive it. Say so
    // rather than leave a spinner that will never stop.
    const settled = stored.map((task): Task =>
      task.status === "running"
        ? {
            ...task,
            status: "failed" as const,
            run: {
              ...task.run,
              failed: true,
              done: true,
              text:
                task.run.text +
                (task.run.text ? "\n\n" : "") +
                "This task was still running when the tab was closed, and v1 runs tasks in the tab. Send it again.",
            },
          }
        : task
    )
    setTasks(settled)
    setSelected(settled[0]?.id ?? null)
    setRestored(true)
  }, [])

  React.useEffect(() => {
    if (restored) saveTasks(tasks)
  }, [tasks, restored])

  const submit = React.useCallback(
    async (event: React.FormEvent) => {
      event.preventDefault()
      const definition = findAgent(slug)
      const text = tasking.trim()
      if (!definition || !text) return

      const task = newTask(definition.slug, definition.name, text)
      setTasks((current) => [task, ...current])
      setSelected(task.id)
      setComposing(false)
      setTasking("")

      const finished = await runAgent({
        agent: definition.slug,
        maxRounds: maxRounds(definition),
        turns: [{ role: "user", text }],
        onUpdate: (run) =>
          setTasks((current) =>
            current.map((entry): Task => (entry.id === task.id ? { ...entry, run } : entry))
          ),
      })

      setTasks((current) =>
        current.map((entry): Task =>
          entry.id === task.id
            ? {
                ...entry,
                run: finished,
                finishedAt: Date.now(),
                status: finished.failed ? "failed" : "delivered",
                deliveredTo: deliveredTo(finished),
              }
            : entry
        )
      )
    },
    [slug, tasking]
  )

  const open = tasks.find((task) => task.id === selected) ?? null

  return (
    <SidebarProvider style={{ "--sidebar-width": "350px" } as React.CSSProperties}>
      <AppSidebar
        tasks={tasks}
        selected={selected}
        onOpenTask={(id) => {
          setSelected(id)
          setComposing(false)
        }}
        onClear={() => {
          setTasks([])
          setSelected(null)
        }}
      />
      <SidebarInset>
        <header className="sticky top-0 flex shrink-0 items-center gap-2 border-b bg-background p-4">
          <SidebarTrigger className="-ml-1" />
          <Separator orientation="vertical" className="mr-2 data-[orientation=vertical]:h-4" />
          <Breadcrumb>
            <BreadcrumbList>
              <BreadcrumbItem className="hidden md:block">
                <BreadcrumbLink href="/agents">Agentic Inbox</BreadcrumbLink>
              </BreadcrumbItem>
              <BreadcrumbSeparator className="hidden md:block" />
              <BreadcrumbItem>
                <BreadcrumbPage>
                  {composing ? "New task" : (open?.agentName ?? "Inbox")}
                </BreadcrumbPage>
              </BreadcrumbItem>
            </BreadcrumbList>
          </Breadcrumb>
          <Button
            size="sm"
            className="ml-auto"
            onClick={() => setComposing(true)}
            disabled={composing}
          >
            New task
          </Button>
        </header>

        <div className="flex flex-1 flex-col gap-4 p-4">
          {composing ? (
            <form className="flex max-w-3xl flex-col gap-3" onSubmit={submit}>
              <div className="flex flex-wrap gap-2">
                {INBOX_AGENTS.map((entry) => (
                  <Button
                    key={entry.slug}
                    type="button"
                    variant={entry.slug === slug ? "default" : "outline"}
                    size="sm"
                    onClick={() => setSlug(entry.slug)}
                  >
                    {entry.name}
                  </Button>
                ))}
              </div>
              <p className="text-sm text-muted-foreground">
                {findAgent(slug)?.speciality}
              </p>
              <Textarea
                value={tasking}
                onChange={(event) => setTasking(event.target.value)}
                placeholder={findAgent(slug)?.placeholder}
                className="min-h-32"
              />
              <div className="flex flex-wrap gap-2">
                {(findAgent(slug)?.starters ?? []).map((starter) => (
                  <Button
                    key={starter}
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => setTasking(starter)}
                  >
                    {starter}
                  </Button>
                ))}
              </div>
              <div className="flex items-center gap-2">
                <Button type="submit" size="sm" disabled={!tasking.trim()}>
                  Send
                </Button>
                <Button type="button" variant="ghost" size="sm" onClick={() => setComposing(false)}>
                  Cancel
                </Button>
                <span className="ml-auto text-xs text-muted-foreground">
                  Runs in this tab. Kept in this browser, not on a server.
                </span>
              </div>
            </form>
          ) : open ? (
            <article className="flex max-w-3xl flex-col gap-4">
              <header className="flex flex-col gap-1">
                <h1 className="text-lg font-semibold tracking-tight">{open.tasking}</h1>
                <p className="text-sm text-muted-foreground">
                  {open.agentName} · {when(open.createdAt)}
                  {open.status === "running" && " · running"}
                  {open.deliveredTo && ` · delivered to ${open.deliveredTo}`}
                </p>
              </header>

              {open.run.text && (
                <div
                  className={
                    open.status === "failed"
                      ? "text-sm whitespace-pre-wrap text-destructive"
                      : "text-sm whitespace-pre-wrap"
                  }
                >
                  <Prose text={open.run.text} />
                </div>
              )}

              {open.status === "running" && (
                // The reading pane's own sign of life. It names the tool in
                // flight rather than saying "working", so a long gather reads
                // as progress instead of as a hang.
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                  <span
                    aria-hidden
                    className="size-2 shrink-0 animate-pulse rounded-full bg-primary"
                  />
                  <span className="animate-pulse">{running(open)}</span>
                </div>
              )}

              {open.run.steps.length > 0 && (
                <details className="rounded-lg border p-3">
                  <summary className="cursor-pointer text-sm text-muted-foreground">
                    {open.run.steps.length} tool call
                    {open.run.steps.length === 1 ? "" : "s"}
                    {open.status === "running" ? " so far" : ""}
                  </summary>
                  <div className="pt-3">
                    <RunSteps steps={open.run.steps} />
                  </div>
                </details>
              )}

              <RunMeta run={open.run} />
            </article>
          ) : (
            <div className="flex max-w-3xl flex-col gap-3">
              <h1 className="text-lg font-semibold tracking-tight">Agentic Inbox</h1>
              <p className="text-sm text-muted-foreground">
                Longer work than a chat: give an agent a task, and its finished report is read
                here like a delivered message, with the run it did underneath. The Researcher
                writes a sourced report over the record; the Tracker watches a topic and posts a
                digest.
              </p>
              <p className="text-sm text-muted-foreground">
                This site is public and has no accounts, so tasks are kept in this browser and
                nowhere else — nobody else can see them, and they do not follow you to another
                device. A task runs while this tab is open. What outlives the tab is the post the
                agent makes to Discord, which is where a finished report actually lands.
              </p>
              <div>
                <Button size="sm" onClick={() => setComposing(true)}>
                  New task
                </Button>
              </div>
            </div>
          )}
        </div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import * as React from "react"
import { AlertCircle, CheckCheck, Command, Inbox, Loader } from "lucide-react"

import { AGENTS } from "@/lib/agents/registry"
import { teaser, when, type Task, type TaskStatus } from "@/lib/agents/inbox"
import { NavUser } from "@/registry/blocks/sidebar-09/components/nav-user"
import { Label } from "@govblock/ui/components/ny4/label"
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarHeader,
  SidebarInput,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@govblock/ui/components/ny4/sidebar"
import { Switch } from "@govblock/ui/components/ny4/switch"

// The Agentic Inbox. This is shadcn's sidebar-09 mail block with its markup and
// classNames intact and its contents replaced: the icon rail filters, the
// second sidebar is the task list rather than a thread list, and each row is an
// agent run — who ran it, what it was asked, and what it is doing right now.
// Repurposed by content; nothing here was redesigned.

const FILTERS: { title: string; icon: typeof Inbox; status: TaskStatus | null }[] = [
  { title: "All", icon: Inbox, status: null },
  { title: "Running", icon: Loader, status: "running" },
  { title: "Delivered", icon: CheckCheck, status: "delivered" },
  { title: "Failed", icon: AlertCircle, status: "failed" },
]

export function AppSidebar({
  tasks,
  selected,
  // Not `onSelect`: Sidebar spreads a div's props, whose own onSelect would
  // intersect with this one and hand the callback a SyntheticEvent.
  onOpenTask,
  onClear,
  ...props
}: React.ComponentProps<typeof Sidebar> & {
  tasks: Task[]
  selected: string | null
  onOpenTask: (id: string) => void
  onClear: () => void
}) {
  const [activeItem, setActiveItem] = React.useState(FILTERS[0]!)
  const [query, setQuery] = React.useState("")
  const [unreadOnly, setUnreadOnly] = React.useState(false)
  const { setOpen } = useSidebar()

  const shown = tasks.filter((task) => {
    if (activeItem.status && task.status !== activeItem.status) return false
    if (unreadOnly && task.status !== "running") return false
    if (!query.trim()) return true
    const hay = `${task.agentName} ${task.tasking} ${task.run.text}`.toLowerCase()
    return hay.includes(query.trim().toLowerCase())
  })

  return (
    <Sidebar
      collapsible="icon"
      className="overflow-hidden *:data-[sidebar=sidebar]:flex-row"
      {...props}
    >
      {/* This is the first sidebar */}
      {/* We disable collapsible and adjust width to icon. */}
      {/* This will make the sidebar appear as icons. */}
      <Sidebar
        collapsible="none"
        className="w-[calc(var(--sidebar-width-icon)+1px)]! border-r"
      >
        <SidebarHeader>
          <SidebarMenu>
            <SidebarMenuItem>
              <SidebarMenuButton size="lg" asChild className="md:h-8 md:p-0">
                <a href="/agents">
                  <div className="flex aspect-square size-8 items-center justify-center rounded-lg bg-sidebar-primary text-sidebar-primary-foreground">
                    <Command className="size-4" />
                  </div>
                  <div className="grid flex-1 text-left text-sm leading-tight">
                    <span className="truncate font-medium">govblock</span>
                    <span className="truncate text-xs">Agentic Inbox</span>
                  </div>
                </a>
              </SidebarMenuButton>
            </SidebarMenuItem>
          </SidebarMenu>
        </SidebarHeader>
        <SidebarContent>
          <SidebarGroup>
            <SidebarGroupContent className="px-1.5 md:px-0">
              <SidebarMenu>
                {FILTERS.map((item) => (
                  <SidebarMenuItem key={item.title}>
                    <SidebarMenuButton
                      tooltip={{ children: item.title, hidden: false }}
                      onClick={() => {
                        setActiveItem(item)
                        setOpen(true)
                      }}
                      isActive={activeItem.title === item.title}
                      className="px-2.5 md:px-2"
                    >
                      <item.icon />
                      <span>{item.title}</span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                ))}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>
        <SidebarFooter>
          <NavUser
            user={{
              name: "This browser",
              email: `${tasks.length} task${tasks.length === 1 ? "" : "s"} kept locally`,
              avatar: "",
            }}
            onClear={onClear}
          />
        </SidebarFooter>
      </Sidebar>

      {/* This is the second sidebar */}
      {/* We disable collapsible and let it fill remaining space */}
      <Sidebar collapsible="none" className="hidden flex-1 md:flex">
        <SidebarHeader className="gap-3.5 border-b p-4">
          <div className="flex w-full items-center justify-between">
            <div className="text-base font-medium text-foreground">{activeItem.title}</div>
            <Label className="flex items-center gap-2 text-sm">
              <span>Running</span>
              <Switch
                className="shadow-none"
                checked={unreadOnly}
                onCheckedChange={(next: boolean) => setUnreadOnly(next)}
              />
            </Label>
          </div>
          <SidebarInput
            placeholder="Type to search…"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
          />
        </SidebarHeader>
        <SidebarContent>
          <SidebarGroup className="px-0">
            <SidebarGroupContent>
              {shown.length === 0 && (
                <p className="p-4 text-sm text-muted-foreground">
                  {tasks.length
                    ? "Nothing here."
                    : `No tasks yet. New task sends one to ${AGENTS.filter((a) => a.inbox || a.agentic).map((a) => a.name).join(" or ")}, and it runs while this tab is open.`}
                </p>
              )}
              {shown.map((task) => (
                <button
                  type="button"
                  key={task.id}
                  onClick={() => onOpenTask(task.id)}
                  data-active={selected === task.id}
                  className="flex w-full flex-col items-start gap-2 border-b p-4 text-left text-sm leading-tight whitespace-nowrap last:border-b-0 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground data-[active=true]:bg-sidebar-accent data-[active=true]:text-sidebar-accent-foreground"
                >
                  <div className="flex w-full items-center gap-2">
                    <span>{task.agentName}</span>{" "}
                    <span className="ml-auto text-xs">{when(task.createdAt)}</span>
                  </div>
                  <span className="w-[260px] truncate font-medium">{task.tasking}</span>
                  <span className="line-clamp-2 flex w-[260px] items-start gap-1.5 text-xs whitespace-break-spaces">
                    {task.status === "running" && (
                      // A running task must never be mistaken for a finished
                      // one. The dot pulses beside whatever tool is in flight.
                      <span
                        aria-hidden
                        className="mt-1 size-1.5 shrink-0 animate-pulse rounded-full bg-primary"
                      />
                    )}
                    <span className={task.status === "running" ? "animate-pulse" : undefined}>
                      {task.status === "failed" && "Failed · "}
                      {teaser(task)}
                    </span>
                  </span>
                </button>
              ))}
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>
      </Sidebar>
    </Sidebar>
  )
}
